// ===== aggregate.js =====
// Ядро расчёта метрик отчёта по задачам Bitrix24.
// Источник правды по формулам — docs/metrics.md.
// Чистый модуль без сетевых вызовов: n8n Code-нода передаёт сюда уже собранные
// массивы и получает готовую раскладку по сотрудникам.

// Коды статусов Bitrix24 (tasks.task.list, поле STATUS). Держим в одном месте —
// если на портале кастомная схема, правим здесь.
const STATUS = { DONE: 5 };

// Дата попадает в период по полуинтервалу [start, end).
function inPeriod(dateStr, period) {
  if (!dateStr) return false;
  const t = new Date(dateStr).getTime();
  return t >= new Date(period.start).getTime() && t < new Date(period.end).getTime();
}

// «Закрыта» = финальный статус (Завершена) И зафиксирована дата закрытия.
function isClosed(task) {
  return task.status === STATUS.DONE && Boolean(task.closedDate);
}

// Приводит «сырую» задачу из ответа API к нормализованному виду (числа/массивы).
function normalizeTask(raw) {
  const toNum = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
  const accomplices = Array.isArray(raw.accomplices) ? raw.accomplices.map(Number) : [];
  return {
    id: toNum(raw.id),
    responsibleId: toNum(raw.responsibleId),
    accomplices,
    status: toNum(raw.status),
    deadline: raw.deadline || null,
    closedDate: raw.closedDate || null,
  };
}

// Классифицирует одну задачу относительно периода (без привязки к сотруднику).
function classifyTask(task, period) {
  const closed = isClosed(task);
  const completedInPeriod = closed && inPeriod(task.closedDate, period);
  const deadlineInPeriod = inPeriod(task.deadline, period);

  // «В срок» — из множества «к выполнению»: закрыта и не позже дедлайна.
  const onTime =
    deadlineInPeriod &&
    closed &&
    new Date(task.closedDate).getTime() <= new Date(task.deadline).getTime();

  // «Просрочено» = «к выполнению» − «в срок».
  const overdue = deadlineInPeriod && !onTime;

  // «Без срока» — среди выполненных за период задачи без дедлайна.
  const noDeadline = completedInPeriod && !task.deadline;

  return { completedInPeriod, deadlineInPeriod, onTime, overdue, noDeadline };
}

function emptyBucket() {
  return { completed: 0, due: 0, onTime: 0, overdue: 0, noDeadline: 0 };
}

function addToBucket(bucket, c) {
  if (c.completedInPeriod) bucket.completed += 1;
  if (c.deadlineInPeriod) bucket.due += 1;
  if (c.onTime) bucket.onTime += 1;
  if (c.overdue) bucket.overdue += 1;
  if (c.noDeadline) bucket.noDeadline += 1;
}

function withRate(bucket) {
  return {
    ...bucket,
    completionRate: bucket.due > 0 ? bucket.onTime / bucket.due : null,
  };
}

// Основная функция: раскладывает задачи по сотрудникам и считает метрики.
// Вход: { users: [{id, name}], tasks: [normalizedTask], period: {start, end},
//   timeSecondsByUser?: {userId: seconds}   — учтённое время (task.elapseditem),
//   deadlineShiftsByTaskId?: {taskId: n}    — число переносов дедлайна по задаче }.
// Выход: массив по каждому сотруднику с разрезами responsible и participation.
function aggregate({ users, tasks, period, timeSecondsByUser = {}, deadlineShiftsByTaskId = {} }) {
  return users.map((user) => {
    const responsible = emptyBucket();
    const participation = emptyBucket();
    let deadlineShifts = 0;
    let tasksRescheduled = 0;

    for (const task of tasks) {
      const isResponsible = task.responsibleId === user.id;
      const isAccomplice = Array.isArray(task.accomplices) && task.accomplices.includes(user.id);
      if (!isResponsible && !isAccomplice) continue; // чужая задача

      const c = classifyTask(task, period);
      // «Участие» — любая роль, задача учитывается один раз (цикл по задачам).
      addToBucket(participation, c);
      // «Как исполнитель» — только где сотрудник RESPONSIBLE_ID.
      if (isResponsible) {
        addToBucket(responsible, c);
        // Переносы дедлайна атрибуцируются исполнителю задачи.
        const shifts = deadlineShiftsByTaskId[task.id] || 0;
        if (shifts > 0) {
          deadlineShifts += shifts;
          tasksRescheduled += 1;
        }
      }
    }

    return {
      userId: user.id,
      name: user.name,
      responsible: withRate(responsible),
      participation: withRate(participation),
      timeSpentSeconds: timeSecondsByUser[user.id] || 0,
      deadlineShifts,
      tasksRescheduled,
    };
  });
}


// ===== period.js =====
// Вычисление границ отчётного периода. Полуинтервал [start, end) в ISO 8601.
// Для month/quarter берётся ПРЕДЫДУЩИЙ период относительно refDate (обычно now):
// отчёт формируется в начале нового периода за только что завершившийся.

const MONTHS_RU = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

const pad = (n) => String(n).padStart(2, '0');
const iso = (y, m, offset) => `${y}-${pad(m)}-01T00:00:00${offset}`; // m: 1..12

function computePeriod(mode, refDate, offset = '+03:00', custom = {}) {
  if (mode === 'custom') {
    return { start: custom.start, end: custom.end, label: 'Произвольный период' };
  }

  // «Текущие» год/месяц по компонентам refDate (UTC — для детерминизма расчёта).
  const y = refDate.getUTCFullYear();
  const m = refDate.getUTCMonth() + 1; // 1..12

  if (mode === 'quarter') {
    const curQ = Math.floor((m - 1) / 3); // 0..3
    let prevQ = curQ - 1;
    let year = y;
    if (prevQ < 0) { prevQ = 3; year -= 1; }
    const startMonth = prevQ * 3 + 1; // 1,4,7,10
    const endMonth = startMonth + 3; // может быть 13 → следующий год
    const end = endMonth > 12 ? iso(year + 1, endMonth - 12, offset) : iso(year, endMonth, offset);
    return { start: iso(year, startMonth, offset), end, label: `Q${prevQ + 1} ${year}` };
  }

  // mode === 'month' (по умолчанию)
  let year = y;
  let month = m - 1; // предыдущий месяц
  if (month < 1) { month = 12; year -= 1; }
  const endMonth = month + 1;
  const end = endMonth > 12 ? iso(year + 1, 1, offset) : iso(year, endMonth, offset);
  return { start: iso(year, month, offset), end, label: `${MONTHS_RU[month - 1]} ${year}` };
}


// ===== report.js =====
// Формирование текста отчёта для отправки в личку руководителю (im.message.add).
// Использует BB-коды Bitrix ([B], [TABLE]) минимально — основной вид текстовый,
// чтобы читалось и в чате, и в уведомлении.

function formatRate(rate) {
  if (rate === null || rate === undefined) return '—';
  return `${Math.round(rate * 100)}%`;
}

// Секунды → часы компактно: 5400 → «1.5ч», 3600 → «1ч».
function formatHours(seconds) {
  const h = Math.round(((seconds || 0) / 3600) * 10) / 10;
  return `${h}ч`;
}

function sum(rows, path) {
  return rows.reduce((acc, r) => acc + (r.responsible[path] || 0), 0);
}

// Сортировка: проблемные выше — сначала по числу просрочек (убыв.),
// затем по % выполнения (возр.), затем по имени.
function sortRows(rows) {
  return [...rows].sort((a, b) => {
    if (b.responsible.overdue !== a.responsible.overdue) {
      return b.responsible.overdue - a.responsible.overdue;
    }
    const ra = a.responsible.completionRate ?? 1;
    const rb = b.responsible.completionRate ?? 1;
    if (ra !== rb) return ra - rb;
    return a.name.localeCompare(b.name, 'ru');
  });
}

// Сотрудник «активен» в периоде, если по разрезу «участие» (исполнитель ИЛИ
// соисполнитель) есть хоть что-то: выполненное или с дедлайном в периоде.
// onTime/overdue/noDeadline — подмножества этих двух, отдельно проверять не надо.
function hasActivity(row) {
  return row.participation.completed > 0 || row.participation.due > 0;
}

function buildReport(allRows, period) {
  const rows = allRows.filter(hasActivity);

  const lines = [];
  lines.push(`[B]Отчёт по задачам — ${period.label}[/B]`);
  lines.push('');

  if (rows.length === 0) {
    lines.push('За период нет данных по сотрудникам.');
    return lines.join('\n');
  }

  // Сводка по компании (по разрезу «как исполнитель»).
  const totalCompleted = sum(rows, 'completed');
  const totalDue = sum(rows, 'due');
  const totalOnTime = sum(rows, 'onTime');
  const totalOverdue = sum(rows, 'overdue');
  const companyRate = totalDue > 0 ? totalOnTime / totalDue : null;

  lines.push(
    `[B]Итого по компании:[/B] выполнено ${totalCompleted}, ` +
      `к выполнению ${totalDue}, в срок ${totalOnTime} (${formatRate(companyRate)}), ` +
      `просрочено ${totalOverdue}`,
  );
  lines.push('');
  lines.push('[B]По сотрудникам[/B] (как исполнитель; в скобках — с учётом соисполнения):');

  for (const r of sortRows(rows)) {
    const resp = r.responsible;
    const part = r.participation;
    const flag = resp.overdue > 0 ? '⚠️ ' : '';
    const noDl = resp.noDeadline > 0 ? `, без срока ${resp.noDeadline}` : '';
    const time = r.timeSpentSeconds > 0 ? `, ⏱ ${formatHours(r.timeSpentSeconds)}` : '';
    const shifts = r.deadlineShifts > 0 ? `, переносы ${r.deadlineShifts}` : '';
    lines.push(
      `${flag}${r.name}: выполнено ${resp.completed} (${part.completed}), ` +
        `в срок ${resp.onTime}/${resp.due} = ${formatRate(resp.completionRate)}, ` +
        `просрочено ${resp.overdue}${noDl}${time}${shifts}`,
    );
  }

  return lines.join('\n');
}

// HTML-версия отчёта — для резервного канала email (n8n Send Email, поле HTML).
function buildReportHtml(allRows, period) {
  const rows = allRows.filter(hasActivity);
  const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  const head = `<h3>Отчёт по задачам — ${esc(period.label)}</h3>`;
  if (rows.length === 0) return `${head}<p>За период нет данных по сотрудникам.</p>`;

  const totalCompleted = sum(rows, 'completed');
  const totalDue = sum(rows, 'due');
  const totalOnTime = sum(rows, 'onTime');
  const totalOverdue = sum(rows, 'overdue');
  const companyRate = totalDue > 0 ? totalOnTime / totalDue : null;

  const summary =
    `<p><b>Итого по компании:</b> выполнено ${totalCompleted}, к выполнению ${totalDue}, ` +
    `в срок ${totalOnTime} (${formatRate(companyRate)}), просрочено ${totalOverdue}</p>`;

  const header =
    '<tr><th align="left">Сотрудник</th><th>Выполнено</th><th>В срок</th><th>%</th>' +
    '<th>Просрочено</th><th>Без срока</th><th>Время</th><th>Переносы</th></tr>';

  const body = sortRows(rows)
    .map((r) => {
      const resp = r.responsible;
      return (
        `<tr><td>${esc(r.name)}</td>` +
        `<td align="center">${resp.completed} (${r.participation.completed})</td>` +
        `<td align="center">${resp.onTime}/${resp.due}</td>` +
        `<td align="center">${formatRate(resp.completionRate)}</td>` +
        `<td align="center">${resp.overdue}</td>` +
        `<td align="center">${resp.noDeadline || ''}</td>` +
        `<td align="center">${r.timeSpentSeconds > 0 ? formatHours(r.timeSpentSeconds) : ''}</td>` +
        `<td align="center">${r.deadlineShifts > 0 ? r.deadlineShifts : ''}</td></tr>`
      );
    })
    .join('');

  const note = '<p style="color:#888;font-size:12px">Формат: как исполнитель (в скобках — с учётом соисполнения).</p>';
  return `${head}${summary}<table border="1" cellpadding="6" cellspacing="0">${header}${body}</table>${note}`;
}


// ===== collect.js =====
// Оркестрация сбора данных из Bitrix24 и формирования отчёта.
// httpRequest инъектируется (в n8n — this.helpers.httpRequest, в тестах — мок),
// поэтому модуль тестируется без живого портала.


const TASK_SELECT = ['ID', 'RESPONSIBLE_ID', 'ACCOMPLICES', 'STATUS', 'DEADLINE', 'CLOSED_DATE', 'CREATED_DATE'];

// Один вызов REST-метода вебхука: <base>/<method>.json (POST JSON).
// ignoreHttpStatusErrors + returnFullResponse: в n8n 2.x Code-нода живёт в task
// runner'е, и исключение axios теряет response.data на RPC-границе — поэтому не
// бросаем на 4xx, а читаем тело сами и достаём error_description Битрикса.
async function callMethod(httpRequest, base, method, body) {
  const url = `${base.replace(/\/$/, '')}/${method}.json`;
  let resp;
  try {
    resp = await httpRequest({
      method: 'POST',
      url,
      body,
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
  } catch (err) {
    // Сетевая ошибка (DNS, таймаут) либо httpRequest без поддержки опций.
    const data = err && err.response && err.response.data ? err.response.data : {};
    const detail = data.error_description || data.error || (err && err.message) || 'unknown error';
    throw new Error(`Bitrix ${method} failed: ${detail}`);
  }

  // При returnFullResponse тело лежит в resp.body; моки/старые версии могут
  // вернуть данные как есть — поддерживаем оба варианта.
  const data = resp && resp.body !== undefined ? resp.body : resp;
  const status = resp && resp.statusCode !== undefined ? resp.statusCode : 200;

  if ((data && data.error) || status >= 400) {
    const detail = (data && (data.error_description || data.error)) || `HTTP ${status}`;
    throw new Error(`Bitrix ${method} failed: ${detail}`);
  }
  return data;
}

// Универсальная постраничная выборка. extract извлекает массив из result,
// пагинация — по полю next (offset). Ограничение на число страниц — предохранитель.
async function fetchAll(httpRequest, base, method, body, extract, maxPages = 200) {
  const out = [];
  let start = 0;
  for (let page = 0; page < maxPages; page += 1) {
    const resp = await callMethod(httpRequest, base, method, { ...body, start });
    const chunk = extract(resp.result) || [];
    out.push(...chunk);
    if (resp.next === undefined || resp.next === null || chunk.length === 0) break;
    start = resp.next;
  }
  return out;
}

async function fetchUsers(httpRequest, base) {
  const raw = await fetchAll(
    httpRequest,
    base,
    'user.get',
    { FILTER: { ACTIVE: true, USER_TYPE: 'employee' } },
    (result) => (Array.isArray(result) ? result : []),
  );
  return raw.map((u) => ({
    id: Number(u.ID),
    name: [u.LAST_NAME, u.NAME].filter(Boolean).join(' ') || `ID ${u.ID}`,
  }));
}

// Учёт времени за период: task.elapseditem.getlist (старый стиль API —
// пагинация через PARAMS.NAV_PARAMS, не через start). Один проход по периоду,
// сумма секунд по каждому пользователю (кто залогировал — тому и время).
async function fetchTimeByUser(httpRequest, base, period, maxPages = 200) {
  const byUser = {};
  for (let page = 1; page <= maxPages; page += 1) {
    // Метод старого стиля: аргументы ПОЗИЦИОННЫЕ (ORDER, FILTER, SELECT, PARAMS).
    // SELECT обязателен, даже пустой — без него PARAMS съезжает на место select
    // и Битрикс отвечает TASKS_ERROR_EXCEPTION_#256 WRONG_ARGUMENTS.
    const resp = await callMethod(httpRequest, base, 'task.elapseditem.getlist', {
      ORDER: { ID: 'asc' },
      FILTER: { '>=CREATED_DATE': period.start, '<CREATED_DATE': period.end },
      SELECT: [],
      PARAMS: { NAV_PARAMS: { nPageSize: 50, iNumPage: page } },
    });
    const chunk = Array.isArray(resp && resp.result) ? resp.result : [];
    for (const rec of chunk) {
      const uid = Number(rec.USER_ID);
      byUser[uid] = (byUser[uid] || 0) + Number(rec.SECONDS || 0);
    }
    if (chunk.length < 50) break;
  }
  return byUser;
}

// Переносы дедлайна одной задачи из истории: пары from→to, где обе стороны
// непустые (первоначальная установка срока переносом не считается).
function countPostponements(entries) {
  let n = 0;
  for (const e of entries) {
    if (e.field !== 'DEADLINE') continue;
    const from = e.value && e.value.from;
    const to = e.value && e.value.to;
    if (from && to && from !== to) n += 1;
  }
  return n;
}

// История дедлайнов по списку задач (по одному запросу на задачу — дорого,
// поэтому есть верхний предел maxTasks; остаток честно возвращаем как skipped).
async function fetchDeadlineShifts(httpRequest, base, taskIds, maxTasks) {
  const shiftsByTaskId = {};
  const scanned = taskIds.slice(0, maxTasks);
  for (const taskId of scanned) {
    const resp = await callMethod(httpRequest, base, 'tasks.task.history.list', {
      taskId,
      filter: { FIELD: 'DEADLINE' },
    });
    const list = resp && resp.result && Array.isArray(resp.result.list) ? resp.result.list : [];
    const n = countPostponements(list);
    if (n > 0) shiftsByTaskId[taskId] = n;
  }
  return { shiftsByTaskId, skipped: taskIds.length - scanned.length };
}

async function fetchTasks(httpRequest, base, filter) {
  const raw = await fetchAll(
    httpRequest,
    base,
    'tasks.task.list',
    { filter, select: TASK_SELECT },
    // tasks.task.list отдаёт result.tasks; на всякий случай поддержим и массив.
    (result) => (result && Array.isArray(result.tasks) ? result.tasks : Array.isArray(result) ? result : []),
  );
  return raw;
}

// Главная функция. config: { webhookBaseUrl, managerDialogId, mode,
// timezoneOffset, start, end }. now инъектируется для детерминизма в тестах.
async function runReport({ config, httpRequest, now = new Date() }) {
  const period = computePeriod(config.mode || 'month', now, config.timezoneOffset || '+03:00', {
    start: config.start,
    end: config.end,
  });

  const users = await fetchUsers(httpRequest, config.webhookBaseUrl);

  const closed = await fetchTasks(httpRequest, config.webhookBaseUrl, {
    '>=CLOSED_DATE': period.start,
    '<CLOSED_DATE': period.end,
  });
  const byDeadline = await fetchTasks(httpRequest, config.webhookBaseUrl, {
    '>=DEADLINE': period.start,
    '<DEADLINE': period.end,
  });

  // Объединяем две выборки и дедуплицируем по id.
  const map = new Map();
  for (const t of [...closed, ...byDeadline]) {
    const n = normalizeTask(t);
    map.set(n.id, n);
  }
  const tasks = [...map.values()];

  // Фаза 2: учтённое время (один пагинируемый запрос за период).
  const timeSecondsByUser =
    config.collectTime === false
      ? {}
      : await fetchTimeByUser(httpRequest, config.webhookBaseUrl, period);

  // Фаза 2: переносы дедлайнов из истории задач с дедлайном в периоде.
  let deadlineShiftsByTaskId = {};
  let historySkipped = 0;
  if (config.collectDeadlineShifts !== false) {
    const dueTaskIds = tasks.filter((t) => inPeriod(t.deadline, period)).map((t) => t.id);
    const { shiftsByTaskId, skipped } = await fetchDeadlineShifts(
      httpRequest,
      config.webhookBaseUrl,
      dueTaskIds,
      config.maxHistoryTasks || 300,
    );
    deadlineShiftsByTaskId = shiftsByTaskId;
    historySkipped = skipped;
  }

  const rows = aggregate({ users, tasks, period, timeSecondsByUser, deadlineShiftsByTaskId });
  const message = buildReport(rows, period);
  const messageHtml = buildReportHtml(rows, period);

  return {
    message,
    messageHtml,
    dialogId: config.managerDialogId,
    period,
    rows,
    tasksCount: tasks.length,
    historySkipped,
  };
}

// Отправка готового сообщения в личку руководителю (im.message.add).
async function sendMessage(httpRequest, base, dialogId, message) {
  return callMethod(httpRequest, base, 'im.message.add', {
    DIALOG_ID: dialogId,
    MESSAGE: message,
  });
}


// ===== n8n glue (Code node, Run Once for All Items) =====
const config = $input.first().json;
const httpRequest = (opts) => this.helpers.httpRequest(opts);

const res = await runReport({ config, httpRequest });

// im.message.add возвращает ID созданного сообщения — это подтверждение доставки.
let sentMessageId = null;
if (!config.dryRun) {
  const sendResp = await sendMessage(httpRequest, config.webhookBaseUrl, config.managerDialogId, res.message);
  sentMessageId = sendResp && sendResp.result ? sendResp.result : null;
}

return [{ json: {
  period: res.period,
  tasksCount: res.tasksCount,
  historySkipped: res.historySkipped,
  dialogId: res.dialogId,
  sent: !config.dryRun,
  sentMessageId,
  message: res.message,
  messageHtml: res.messageHtml,
} }];
